/**
 * Error types and source marks, mirroring PyYAML's `yaml.error` module so the
 * messages we print to stderr line up with the Python original.
 */

import { LINEBREAKS_OR_NULL } from './chars.mjs';

export class Mark {
  /**
   * @param {string} name        stream name, e.g. "<unicode string>"
   * @param {number} index       code point offset
   * @param {number} line        0-based
   * @param {number} column      0-based
   * @param {string[]|null} buffer array of code points (with trailing '\0')
   * @param {number} pointer     index into `buffer`
   */
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let head = '';
    let start = this.pointer;
    while (start > 0 && !LINEBREAKS_OR_NULL.has(this.buffer[start - 1])) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && !LINEBREAKS_OR_NULL.has(this.buffer[end])) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        break;
      }
    }
    const snippet = this.buffer.slice(start, end).join('');
    return (
      ' '.repeat(indent) + head + snippet + tail + '\n' +
      ' '.repeat(indent + this.pointer - start + head.length) + '^'
    );
  }

  toString() {
    const snippet = this.getSnippet();
    let where = `  in "${this.name}", line ${this.line + 1}, column ${this.column + 1}`;
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.name = 'YAMLError';
    this.qualifiedName = 'yaml.error.YAMLError';
  }
}

export class MarkedYAMLError extends YAMLError {
  constructor(context, contextMark, problem, problemMark, note = null) {
    super('');
    this.context = context ?? null;
    this.contextMark = contextMark ?? null;
    this.problem = problem ?? null;
    this.problemMark = problemMark ?? null;
    this.note = note ?? null;
    this.name = 'MarkedYAMLError';
    this.message = this.describe();
  }

  describe() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (
      this.contextMark !== null &&
      (this.problem === null ||
        this.problemMark === null ||
        this.contextMark.name !== this.problemMark.name ||
        this.contextMark.line !== this.problemMark.line ||
        this.contextMark.column !== this.problemMark.column)
    ) {
      lines.push(String(this.contextMark));
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(String(this.problemMark));
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }

  toString() {
    return this.describe();
  }
}

function marked(name, qualifiedName) {
  const cls = class extends MarkedYAMLError {
    constructor(context, contextMark, problem, problemMark, note = null) {
      super(context, contextMark, problem, problemMark, note);
      this.name = name;
      this.qualifiedName = qualifiedName;
    }
  };
  Object.defineProperty(cls, 'name', { value: name });
  return cls;
}

export const ScannerError = marked('ScannerError', 'yaml.scanner.ScannerError');
export const ParserError = marked('ParserError', 'yaml.parser.ParserError');
export const ComposerError = marked('ComposerError', 'yaml.composer.ComposerError');
export const ConstructorError = marked('ConstructorError', 'yaml.constructor.ConstructorError');

export class ReaderError extends YAMLError {
  constructor(name, position, character, encoding, reason) {
    super('');
    this.streamName = name;
    this.position = position;
    this.character = character;
    this.encoding = encoding;
    this.reason = reason;
    this.name = 'ReaderError';
    this.qualifiedName = 'yaml.reader.ReaderError';
    this.message = this.describe();
  }

  describe() {
    const code = this.character.codePointAt(0).toString(16);
    return (
      `unacceptable character #x${code}: ${this.reason}\n` +
      `  in "${this.streamName}", position ${this.position}`
    );
  }

  toString() {
    return this.describe();
  }
}

export class EmitterError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'EmitterError';
    this.qualifiedName = 'yaml.emitter.EmitterError';
  }
}

export class SerializerError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'SerializerError';
    this.qualifiedName = 'yaml.serializer.SerializerError';
  }
}

export class RepresenterError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'RepresenterError';
    this.qualifiedName = 'yaml.representer.RepresenterError';
  }
}

/** Stand-in for Python's TypeError, used by the sorting helpers. */
export class PyTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'TypeError';
    this.qualifiedName = 'TypeError';
  }
}

/** Stand-in for Python's ValueError. */
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
    this.qualifiedName = 'ValueError';
  }
}

