/**
 * Code-point oriented stream reader (port of PyYAML's `yaml.reader.Reader`
 * for the "already a unicode string" case).
 */

import { codePoints, isPrintable, LINEBREAKS_OR_NULL } from './chars.mjs';
import { Mark, ReaderError } from './errors.mjs';

const STREAM_NAME = '<unicode string>';

export class Reader {
  constructor(text) {
    this.name = STREAM_NAME;
    this.checkPrintable(text);
    this.buffer = codePoints(text);
    this.buffer.push('\0');
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
  }

  checkPrintable(text) {
    let index = 0;
    for (const ch of text) {
      if (!isPrintable(ch)) {
        throw new ReaderError(
          STREAM_NAME,
          index,
          ch,
          'unicode',
          'special characters are not allowed',
        );
      }
      index += 1;
    }
  }

  peek(index = 0) {
    const ch = this.buffer[this.pointer + index];
    return ch === undefined ? '\0' : ch;
  }

  prefix(length = 1) {
    return this.buffer.slice(this.pointer, this.pointer + length).join('');
  }

  forward(length = 1) {
    let remaining = length;
    while (remaining) {
      const ch = this.buffer[this.pointer];
      this.pointer += 1;
      this.index += 1;
      if (
        ch === '\n' || ch === '\x85' || ch === ' ' || ch === ' ' ||
        (ch === '\r' && this.buffer[this.pointer] !== '\n')
      ) {
        this.line += 1;
        this.column = 0;
      } else if (ch !== '﻿') {
        this.column += 1;
      }
      remaining -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column, this.buffer, this.pointer);
  }
}

export { LINEBREAKS_OR_NULL };

