/**
 * Character classification helpers.
 *
 * Everything here works on single code points represented as JavaScript
 * strings (which may be two UTF-16 units long for astral characters), so the
 * rest of the pipeline can reason in code points exactly like Python does.
 * No regular expressions are used anywhere in this project.
 */

/** Unicode line separators PyYAML treats as line breaks. */
export const NEL = '';
export const LS = ' ';
export const PS = ' ';
export const BOM = '﻿';

/** Split a string into an array of code points. */
export function codePoints(text) {
  const out = [];
  for (const ch of text) out.push(ch);
  return out;
}

/** Number of code points in a string (Python's len() for str). */
export function cpLength(text) {
  let n = 0;
  for (const _ of text) n += 1;
  return n;
}

function setOf(chars) {
  const s = new Set();
  for (const ch of chars) s.add(ch);
  return s;
}

export const LINEBREAKS = setOf(['\r', '\n', NEL, LS, PS]);
export const LINEBREAKS_OR_NULL = setOf(['\0', '\r', '\n', NEL, LS, PS]);
export const SPACE_TAB = setOf([' ', '\t']);
export const BLANK_OR_BREAK = setOf([' ', '\t', '\r', '\n', NEL, LS, PS]);
export const BLANK_BREAK_OR_NULL = setOf(['\0', ' ', '\t', '\r', '\n', NEL, LS, PS]);

export function isLineBreak(ch) {
  return LINEBREAKS.has(ch);
}

export function isBlankOrBreakOrNull(ch) {
  return BLANK_BREAK_OR_NULL.has(ch);
}

export function isBreakOrNull(ch) {
  return LINEBREAKS_OR_NULL.has(ch);
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'F') || (ch >= 'a' && ch <= 'f');
}

/** Matches PyYAML's `'0' <= ch <= '9' or 'A' <= ch <= 'Z' or 'a' <= ch <= 'z'`. */
export function isAsciiAlnum(ch) {
  return (
    (ch >= '0' && ch <= '9') ||
    (ch >= 'A' && ch <= 'Z') ||
    (ch >= 'a' && ch <= 'z')
  );
}

export function isNameChar(ch) {
  return isAsciiAlnum(ch) || ch === '-' || ch === '_';
}

const TAG_URI_EXTRA = setOf("-;/?:@&=+$,_.!~*'()[]%");

export function isTagUriChar(ch) {
  return isAsciiAlnum(ch) || TAG_URI_EXTRA.has(ch);
}

const TAG_HANDLE_EXTRA = setOf("-;/?:@&=+$,_.!~*'()[]");

/** Characters allowed in the suffix of a `!`-shorthand tag (no '%'). */
export function isTagShorthandChar(ch) {
  return isAsciiAlnum(ch) || TAG_HANDLE_EXTRA.has(ch);
}

export function hexValue(ch) {
  if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
  if (ch >= 'a' && ch <= 'f') return ch.charCodeAt(0) - 87;
  if (ch >= 'A' && ch <= 'F') return ch.charCodeAt(0) - 55;
  return -1;
}

/**
 * PyYAML's Reader.NON_PRINTABLE rejects anything outside
 * \x09 \x0A \x0D \x20-\x7E \x85 \xA0-퟿ -� \u{10000}-\u{10FFFF}
 */
export function isPrintable(ch) {
  const c = ch.codePointAt(0);
  if (c === 0x09 || c === 0x0a || c === 0x0d || c === 0x85) return true;
  if (c >= 0x20 && c <= 0x7e) return true;
  if (c >= 0xa0 && c <= 0xd7ff) return true;
  if (c >= 0xe000 && c <= 0xfffd) return true;
  if (c >= 0x10000 && c <= 0x10ffff) return true;
  return false;
}

/** Lowercase an ASCII string without touching anything else. */
export function asciiLower(text) {
  let out = '';
  for (const ch of text) {
    out += ch >= 'A' && ch <= 'Z' ? String.fromCharCode(ch.charCodeAt(0) + 32) : ch;
  }
  return out;
}

