/**
 * Minimal stand-in for Python's `repr()` of strings, used to build scanner and
 * parser error messages that read the same as PyYAML's.
 */

const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

function hexEscape(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * `repr()` for a string. Python prefers single quotes and switches to double
 * quotes when the value contains a single quote but no double quote.
 */
export function pyRepr(text) {
  let hasSingle = false;
  let hasDouble = false;
  for (const ch of text) {
    if (ch === "'") hasSingle = true;
    else if (ch === '"') hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let body = '';
  for (const ch of text) {
    if (ch === quote) {
      body += '\\' + ch;
      continue;
    }
    const short = SHORT_ESCAPES.get(ch);
    if (short !== undefined) {
      body += short;
      continue;
    }
    const cp = ch.codePointAt(0);
    // Python renders printable characters literally; we treat non-ASCII as
    // printable except for the C1 range and the separators, matching CPython
    // for every character YAML input can realistically carry.
    if (cp < 0x20 || cp === 0x7f || (cp >= 0x80 && cp <= 0xa0) || cp === 0xad ||
        cp === 0x2028 || cp === 0x2029 || cp === 0xfeff) {
      body += hexEscape(cp);
    } else {
      body += ch;
    }
  }
  return quote + body + quote;
}

