/**
 * YAML scanner: turns a character stream into tokens.
 *
 * This is a faithful port of PyYAML's `yaml.scanner.Scanner`, including its
 * simple-key bookkeeping and its (deliberately quirky) block-scalar folding
 * rules, so that acceptance and error behaviour line up with the original.
 */

import {
  BLANK_BREAK_OR_NULL,
  LINEBREAKS,
  LINEBREAKS_OR_NULL,
  NEL,
  LS,
  PS,
  BOM,
  SPACE_BREAK_OR_NULL,
  SPACE_TAB,
  isDigit,
  isHexDigit,
  isNameChar,
  isTagUriChar,
  hexValue,
} from './chars.mjs';
import { ScannerError } from './errors.mjs';
import { pyRepr } from './pyrepr.mjs';
import { Reader } from './reader.mjs';
import {
  AliasToken,
  AnchorToken,
  BlockEndToken,
  BlockEntryToken,
  BlockMappingStartToken,
  BlockSequenceStartToken,
  DirectiveToken,
  DocumentEndToken,
  DocumentStartToken,
  FlowEntryToken,
  FlowMappingEndToken,
  FlowMappingStartToken,
  FlowSequenceEndToken,
  FlowSequenceStartToken,
  KeyToken,
  ScalarToken,
  StreamEndToken,
  StreamStartToken,
  TagToken,
  ValueToken,
} from './tokens.mjs';

const ESCAPE_REPLACEMENTS = new Map([
  ['0', '\0'],
  ['a', '\x07'],
  ['b', '\x08'],
  ['t', '\x09'],
  ['\t', '\x09'],
  ['n', '\x0a'],
  ['v', '\x0b'],
  ['f', '\x0c'],
  ['r', '\x0d'],
  ['e', '\x1b'],
  [' ', '\x20'],
  ['"', '"'],
  ['\\', '\\'],
  ['/', '/'],
  ['N', NEL],
  ['_', '\xa0'],
  ['L', LS],
  ['P', PS],
]);

const ESCAPE_CODES = new Map([
  ['x', 2],
  ['u', 4],
  ['U', 8],
]);

function setOf(chars) {
  const s = new Set();
  for (const ch of chars) s.add(ch);
  return s;
}

/** Terminators allowed right after an anchor/alias name. */
const ANCHOR_END = setOf(['\0', ' ', '\t', '\r', '\n', NEL, LS, PS, '?', ':', ',', ']', '}', '%', '@', '`']);
/** Characters that cannot start a plain scalar on their own. */
const PLAIN_FORBIDDEN_FIRST = setOf([
  '\0', ' ', '\t', '\r', '\n', NEL, LS, PS,
  '-', '?', ':', ',', '[', ']', '{', '}', '#', '&', '*', '!', '|', '>',
  "'", '"', '%', '@', '`',
]);
const FLOW_INDICATORS = setOf([',', '?', '[', ']', '{', '}']);
const PLAIN_COLON_FLOW_END = setOf(['\0', ' ', '\t', '\r', '\n', NEL, LS, PS, ',', '[', ']', '{', '}']);

class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

export class Scanner {
  constructor(text) {
    this.reader = new Reader(text);

    this.done = false;
    this.flowLevel = 0;
    this.tokens = [];
    this.tokensTaken = 0;
    this.indent = -1;
    this.indents = [];
    this.allowSimpleKey = true;
    /** @type {Map<number, SimpleKey>} */
    this.possibleSimpleKeys = new Map();

    this.fetchStreamStart();
  }

  // ---- reader shortcuts -------------------------------------------------

  peek(index = 0) {
    return this.reader.peek(index);
  }

  prefix(length = 1) {
    return this.reader.prefix(length);
  }

  forward(length = 1) {
    this.reader.forward(length);
  }

  getMark() {
    return this.reader.getMark();
  }

  get column() {
    return this.reader.column;
  }

  get line() {
    return this.reader.line;
  }

  get index() {
    return this.reader.index;
  }

  // ---- public token API -------------------------------------------------

  checkToken(...ids) {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) {
      if (!ids.length) return true;
      for (const id of ids) {
        if (this.tokens[0].id === id) return true;
      }
    }
    return false;
  }

  peekToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    return this.tokens.length ? this.tokens[0] : null;
  }

  getToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (!this.tokens.length) return null;
    this.tokensTaken += 1;
    return this.tokens.shift();
  }

  needMoreTokens() {
    if (this.done) return false;
    if (!this.tokens.length) return true;
    this.stalePossibleSimpleKeys();
    return this.nextPossibleSimpleKey() === this.tokensTaken;
  }

  // ---- simple keys ------------------------------------------------------

  nextPossibleSimpleKey() {
    let minTokenNumber = null;
    for (const key of this.possibleSimpleKeys.values()) {
      if (minTokenNumber === null || key.tokenNumber < minTokenNumber) {
        minTokenNumber = key.tokenNumber;
      }
    }
    return minTokenNumber;
  }

  stalePossibleSimpleKeys() {
    for (const level of [...this.possibleSimpleKeys.keys()]) {
      const key = this.possibleSimpleKeys.get(level);
      if (key.line !== this.line || this.index - key.index > 1024) {
        if (key.required) {
          throw new ScannerError(
            'while scanning a simple key', key.mark,
            "could not find expected ':'", this.getMark(),
          );
        }
        this.possibleSimpleKeys.delete(level);
      }
    }
  }

  savePossibleSimpleKey() {
    const required = !this.flowLevel && this.indent === this.column;
    if (this.allowSimpleKey) {
      this.removePossibleSimpleKey();
      const tokenNumber = this.tokensTaken + this.tokens.length;
      const key = new SimpleKey(
        tokenNumber, required, this.index, this.line, this.column, this.getMark(),
      );
      this.possibleSimpleKeys.set(this.flowLevel, key);
    }
  }

  removePossibleSimpleKey() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      if (key.required) {
        throw new ScannerError(
          'while scanning a simple key', key.mark,
          "could not find expected ':'", this.getMark(),
        );
      }
      this.possibleSimpleKeys.delete(this.flowLevel);
    }
  }

  // ---- indentation ------------------------------------------------------

  unwindIndent(column) {
    if (this.flowLevel) return;
    while (this.indent > column) {
      const mark = this.getMark();
      this.indent = this.indents.pop();
      this.tokens.push(new BlockEndToken(mark, mark));
    }
  }

  addIndent(column) {
    if (this.indent < column) {
      this.indents.push(this.indent);
      this.indent = column;
      return true;
    }
    return false;
  }

  // ---- dispatch ---------------------------------------------------------

  fetchMoreTokens() {
    this.scanToNextToken();
    this.stalePossibleSimpleKeys();
    this.unwindIndent(this.column);

    const ch = this.peek();
    if (ch === '\0') return this.fetchStreamEnd();
    if (ch === '%' && this.checkDirective()) return this.fetchDirective();
    if (ch === '-' && this.checkDocumentStart()) return this.fetchDocumentStart();
    if (ch === '.' && this.checkDocumentEnd()) return this.fetchDocumentEnd();
    if (ch === '[') return this.fetchFlowCollectionStart(FlowSequenceStartToken);
    if (ch === '{') return this.fetchFlowCollectionStart(FlowMappingStartToken);
    if (ch === ']') return this.fetchFlowCollectionEnd(FlowSequenceEndToken);
    if (ch === '}') return this.fetchFlowCollectionEnd(FlowMappingEndToken);
    if (ch === ',') return this.fetchFlowEntry();
    if (ch === '-' && this.checkBlockEntry()) return this.fetchBlockEntry();
    if (ch === '?' && this.checkKey()) return this.fetchKey();
    if (ch === ':' && this.checkValue()) return this.fetchValue();
    if (ch === '*') return this.fetchAlias();
    if (ch === '&') return this.fetchAnchor();
    if (ch === '!') return this.fetchTag();
    if (ch === '|' && !this.flowLevel) return this.fetchBlockScalar('|');
    if (ch === '>' && !this.flowLevel) return this.fetchBlockScalar('>');
    if (ch === "'") return this.fetchFlowScalar("'");
    if (ch === '"') return this.fetchFlowScalar('"');
    if (this.checkPlain()) return this.fetchPlain();
    throw new ScannerError(
      'while scanning for the next token', null,
      `found character ${pyRepr(ch)} that cannot start any token`,
      this.getMark(),
    );
  }

  // ---- checkers ---------------------------------------------------------

  checkDirective() {
    return this.column === 0;
  }

  checkDocumentStart() {
    return this.column === 0 && this.prefix(3) === '---' && BLANK_BREAK_OR_NULL.has(this.peek(3));
  }

  checkDocumentEnd() {
    return this.column === 0 && this.prefix(3) === '...' && BLANK_BREAK_OR_NULL.has(this.peek(3));
  }

  checkBlockEntry() {
    return BLANK_BREAK_OR_NULL.has(this.peek(1));
  }

  checkKey() {
    if (this.flowLevel) return true;
    return BLANK_BREAK_OR_NULL.has(this.peek(1));
  }

  checkValue() {
    if (this.flowLevel) return true;
    return BLANK_BREAK_OR_NULL.has(this.peek(1));
  }

  checkPlain() {
    const ch = this.peek();
    return (
      !PLAIN_FORBIDDEN_FIRST.has(ch) ||
      (!BLANK_BREAK_OR_NULL.has(this.peek(1)) &&
        (ch === '-' || (!this.flowLevel && (ch === '?' || ch === ':'))))
    );
  }

  // ---- fetchers ---------------------------------------------------------

  fetchStreamStart() {
    const mark = this.getMark();
    this.tokens.push(new StreamStartToken(mark, mark, null));
  }

  fetchStreamEnd() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.possibleSimpleKeys = new Map();
    const mark = this.getMark();
    this.tokens.push(new StreamEndToken(mark, mark));
    this.done = true;
  }

  fetchDirective() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanDirective());
  }

  fetchDocumentStart() {
    this.fetchDocumentIndicator(DocumentStartToken);
  }

  fetchDocumentEnd() {
    this.fetchDocumentIndicator(DocumentEndToken);
  }

  fetchDocumentIndicator(TokenClass) {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward(3);
    const endMark = this.getMark();
    this.tokens.push(new TokenClass(startMark, endMark));
  }

  fetchFlowCollectionStart(TokenClass) {
    this.savePossibleSimpleKey();
    this.flowLevel += 1;
    this.allowSimpleKey = true;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new TokenClass(startMark, endMark));
  }

  fetchFlowCollectionEnd(TokenClass) {
    this.removePossibleSimpleKey();
    this.flowLevel -= 1;
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new TokenClass(startMark, endMark));
  }

  fetchFlowEntry() {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new FlowEntryToken(startMark, endMark));
  }

  fetchBlockEntry() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(
          null, null, 'sequence entries are not allowed here', this.getMark(),
        );
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new BlockSequenceStartToken(mark, mark));
      }
    }
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new BlockEntryToken(startMark, endMark));
  }

  fetchKey() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(
          null, null, 'mapping keys are not allowed here', this.getMark(),
        );
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new BlockMappingStartToken(mark, mark));
      }
    }
    this.allowSimpleKey = false;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new KeyToken(startMark, endMark));
  }

  fetchValue() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      this.possibleSimpleKeys.delete(this.flowLevel);
      this.tokens.splice(
        key.tokenNumber - this.tokensTaken, 0, new KeyToken(key.mark, key.mark),
      );
      if (!this.flowLevel) {
        if (this.addIndent(key.column)) {
          this.tokens.splice(
            key.tokenNumber - this.tokensTaken, 0,
            new BlockMappingStartToken(key.mark, key.mark),
          );
        }
      }
      this.allowSimpleKey = false;
    } else {
      if (!this.flowLevel) {
        if (!this.allowSimpleKey) {
          throw new ScannerError(
            null, null, 'mapping values are not allowed here', this.getMark(),
          );
        }
        if (this.addIndent(this.column)) {
          const mark = this.getMark();
          this.tokens.push(new BlockMappingStartToken(mark, mark));
        }
      }
      this.allowSimpleKey = !this.flowLevel;
      this.removePossibleSimpleKey();
    }
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new ValueToken(startMark, endMark));
  }

  fetchAlias() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(AliasToken));
  }

  fetchAnchor() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(AnchorToken));
  }

  fetchTag() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanTag());
  }

  fetchBlockScalar(style) {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    this.tokens.push(this.scanBlockScalar(style));
  }

  fetchFlowScalar(style) {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanFlowScalar(style));
  }

  fetchPlain() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanPlain());
  }

  // ---- scanners ---------------------------------------------------------

  scanToNextToken() {
    if (this.index === 0 && this.peek() === BOM) this.forward();
    let found = false;
    while (!found) {
      while (this.peek() === ' ') this.forward();
      if (this.peek() === '#') {
        while (!LINEBREAKS_OR_NULL.has(this.peek())) this.forward();
      }
      if (this.scanLineBreak()) {
        if (!this.flowLevel) this.allowSimpleKey = true;
      } else {
        found = true;
      }
    }
  }

  scanDirective() {
    const startMark = this.getMark();
    this.forward();
    const name = this.scanDirectiveName(startMark);
    let value = null;
    let endMark;
    if (name === 'YAML') {
      value = this.scanYamlDirectiveValue(startMark);
      endMark = this.getMark();
    } else if (name === 'TAG') {
      value = this.scanTagDirectiveValue(startMark);
      endMark = this.getMark();
    } else {
      endMark = this.getMark();
      while (!LINEBREAKS_OR_NULL.has(this.peek())) this.forward();
    }
    this.scanDirectiveIgnoredLine(startMark);
    return new DirectiveToken(name, value, startMark, endMark);
  }

  scanDirectiveName(startMark) {
    let length = 0;
    let ch = this.peek(length);
    while (isNameChar(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found ${pyRepr(ch)}`,
        this.getMark(),
      );
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!SPACE_BREAK_OR_NULL.has(ch)) {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found ${pyRepr(ch)}`,
        this.getMark(),
      );
    }
    return value;
  }

  scanYamlDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const major = this.scanYamlDirectiveNumber(startMark);
    if (this.peek() !== '.') {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected a digit or '.', but found ${pyRepr(this.peek())}`,
        this.getMark(),
      );
    }
    this.forward();
    const minor = this.scanYamlDirectiveNumber(startMark);
    if (!SPACE_BREAK_OR_NULL.has(this.peek())) {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected a digit or ' ', but found ${pyRepr(this.peek())}`,
        this.getMark(),
      );
    }
    return [major, minor];
  }

  scanYamlDirectiveNumber(startMark) {
    const ch = this.peek();
    if (!isDigit(ch)) {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected a digit, but found ${pyRepr(ch)}`, this.getMark(),
      );
    }
    let length = 0;
    while (isDigit(this.peek(length))) length += 1;
    const value = Number.parseInt(this.prefix(length), 10);
    this.forward(length);
    return value;
  }

  scanTagDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const handle = this.scanTagDirectiveHandle(startMark);
    while (this.peek() === ' ') this.forward();
    const prefix = this.scanTagDirectivePrefix(startMark);
    return [handle, prefix];
  }

  scanTagDirectiveHandle(startMark) {
    const value = this.scanTagHandle('directive', startMark);
    const ch = this.peek();
    if (ch !== ' ') {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected ' ', but found ${pyRepr(ch)}`, this.getMark(),
      );
    }
    return value;
  }

  scanTagDirectivePrefix(startMark) {
    const value = this.scanTagUri('directive', startMark);
    const ch = this.peek();
    if (!SPACE_BREAK_OR_NULL.has(ch)) {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected ' ', but found ${pyRepr(ch)}`, this.getMark(),
      );
    }
    return value;
  }

  scanDirectiveIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!LINEBREAKS_OR_NULL.has(this.peek())) this.forward();
    }
    const ch = this.peek();
    if (!LINEBREAKS_OR_NULL.has(ch)) {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected a comment or a line break, but found ${pyRepr(ch)}`,
        this.getMark(),
      );
    }
    this.scanLineBreak();
  }

  scanAnchor(TokenClass) {
    const startMark = this.getMark();
    const indicator = this.peek();
    const name = indicator === '*' ? 'alias' : 'anchor';
    this.forward();
    let length = 0;
    let ch = this.peek(length);
    while (isNameChar(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError(
        `while scanning an ${name}`, startMark,
        `expected alphabetic or numeric character, but found ${pyRepr(ch)}`,
        this.getMark(),
      );
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!ANCHOR_END.has(ch)) {
      throw new ScannerError(
        `while scanning an ${name}`, startMark,
        `expected alphabetic or numeric character, but found ${pyRepr(ch)}`,
        this.getMark(),
      );
    }
    const endMark = this.getMark();
    return new TokenClass(value, startMark, endMark);
  }

  scanTag() {
    const startMark = this.getMark();
    let ch = this.peek(1);
    let handle;
    let suffix;
    if (ch === '<') {
      handle = null;
      this.forward(2);
      suffix = this.scanTagUri('tag', startMark);
      if (this.peek() !== '>') {
        throw new ScannerError(
          'while parsing a tag', startMark,
          `expected '>', but found ${pyRepr(this.peek())}`, this.getMark(),
        );
      }
      this.forward();
    } else if (BLANK_BREAK_OR_NULL.has(ch)) {
      handle = null;
      suffix = '!';
      this.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!SPACE_BREAK_OR_NULL.has(ch)) {
        if (ch === '!') {
          useHandle = true;
          break;
        }
        length += 1;
        ch = this.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.peek();
    if (!SPACE_BREAK_OR_NULL.has(ch)) {
      throw new ScannerError(
        'while scanning a tag', startMark,
        `expected ' ', but found ${pyRepr(ch)}`, this.getMark(),
      );
    }
    const endMark = this.getMark();
    return new TagToken([handle, suffix], startMark, endMark);
  }

  scanBlockScalar(style) {
    const folded = style === '>';
    const chunks = [];
    const startMark = this.getMark();

    this.forward();
    const [chomping, increment] = this.scanBlockScalarIndicators(startMark);
    this.scanBlockScalarIgnoredLine(startMark);

    let minIndent = this.indent + 1;
    if (minIndent < 1) minIndent = 1;
    let indent;
    let breaks;
    let endMark;
    if (increment === null) {
      const res = this.scanBlockScalarIndentation();
      breaks = res[0];
      const maxIndent = res[1];
      endMark = res[2];
      indent = Math.max(minIndent, maxIndent);
    } else {
      indent = minIndent + increment - 1;
      const res = this.scanBlockScalarBreaks(indent);
      breaks = res[0];
      endMark = res[1];
    }

    let lineBreak = '';
    while (this.column === indent && this.peek() !== '\0') {
      chunks.push(...breaks);
      const leadingNonSpace = !SPACE_TAB.has(this.peek());
      let length = 0;
      while (!LINEBREAKS_OR_NULL.has(this.peek(length))) length += 1;
      chunks.push(this.prefix(length));
      this.forward(length);
      lineBreak = this.scanLineBreak();
      const res = this.scanBlockScalarBreaks(indent);
      breaks = res[0];
      endMark = res[1];
      if (this.column === indent && this.peek() !== '\0') {
        if (folded && lineBreak === '\n' && leadingNonSpace && !SPACE_TAB.has(this.peek())) {
          if (!breaks.length) chunks.push(' ');
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }

    if (chomping !== false) chunks.push(lineBreak);
    if (chomping === true) chunks.push(...breaks);

    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.peek();
    if (ch === '+' || ch === '-') {
      chomping = ch === '+';
      this.forward();
      ch = this.peek();
      if (isDigit(ch)) {
        increment = ch.charCodeAt(0) - 48;
        if (increment === 0) {
          throw new ScannerError(
            'while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1-9, but found 0',
            this.getMark(),
          );
        }
        this.forward();
      }
    } else if (isDigit(ch)) {
      increment = ch.charCodeAt(0) - 48;
      if (increment === 0) {
        throw new ScannerError(
          'while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1-9, but found 0',
          this.getMark(),
        );
      }
      this.forward();
      ch = this.peek();
      if (ch === '+' || ch === '-') {
        chomping = ch === '+';
        this.forward();
      }
    }
    ch = this.peek();
    if (!SPACE_BREAK_OR_NULL.has(ch)) {
      throw new ScannerError(
        'while scanning a block scalar', startMark,
        `expected chomping or indentation indicators, but found ${pyRepr(ch)}`,
        this.getMark(),
      );
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!LINEBREAKS_OR_NULL.has(this.peek())) this.forward();
    }
    const ch = this.peek();
    if (!LINEBREAKS_OR_NULL.has(ch)) {
      throw new ScannerError(
        'while scanning a block scalar', startMark,
        `expected a comment or a line break, but found ${pyRepr(ch)}`,
        this.getMark(),
      );
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.getMark();
    while (this.peek() === ' ' || LINEBREAKS.has(this.peek())) {
      if (this.peek() !== ' ') {
        chunks.push(this.scanLineBreak());
        endMark = this.getMark();
      } else {
        this.forward();
        if (this.column > maxIndent) maxIndent = this.column;
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.getMark();
    while (this.column < indent && this.peek() === ' ') this.forward();
    while (LINEBREAKS.has(this.peek())) {
      chunks.push(this.scanLineBreak());
      endMark = this.getMark();
      while (this.column < indent && this.peek() === ' ') this.forward();
    }
    return [chunks, endMark];
  }

  scanFlowScalar(style) {
    const double = style === '"';
    const chunks = [];
    const startMark = this.getMark();
    const quote = this.peek();
    this.forward();
    chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    while (this.peek() !== quote) {
      chunks.push(...this.scanFlowScalarSpaces(double, startMark));
      chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    }
    this.forward();
    const endMark = this.getMark();
    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const chunks = [];
    for (;;) {
      let length = 0;
      for (;;) {
        const c = this.peek(length);
        if (c === "'" || c === '"' || c === '\\' || BLANK_BREAK_OR_NULL.has(c)) break;
        length += 1;
      }
      if (length) {
        chunks.push(this.prefix(length));
        this.forward(length);
      }
      let ch = this.peek();
      if (!double && ch === "'" && this.peek(1) === "'") {
        chunks.push("'");
        this.forward(2);
      } else if ((double && ch === "'") || (!double && (ch === '"' || ch === '\\'))) {
        chunks.push(ch);
        this.forward();
      } else if (double && ch === '\\') {
        this.forward();
        ch = this.peek();
        if (ESCAPE_REPLACEMENTS.has(ch)) {
          chunks.push(ESCAPE_REPLACEMENTS.get(ch));
          this.forward();
        } else if (ESCAPE_CODES.has(ch)) {
          length = ESCAPE_CODES.get(ch);
          this.forward();
          for (let k = 0; k < length; k += 1) {
            if (!isHexDigit(this.peek(k))) {
              throw new ScannerError(
                'while scanning a double-quoted scalar', startMark,
                `expected escape sequence of ${length} hexdecimal numbers, but found ${pyRepr(this.peek(k))}`,
                this.getMark(),
              );
            }
          }
          let code = 0;
          for (let k = 0; k < length; k += 1) code = code * 16 + hexValue(this.peek(k));
          chunks.push(codePointToString(code, startMark, this));
          this.forward(length);
        } else if (LINEBREAKS.has(ch)) {
          this.scanLineBreak();
          chunks.push(...this.scanFlowScalarBreaks(double, startMark));
        } else {
          throw new ScannerError(
            'while scanning a double-quoted scalar', startMark,
            `found unknown escape character ${pyRepr(ch)}`, this.getMark(),
          );
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (SPACE_TAB.has(this.peek(length))) length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (ch === '\0') {
      throw new ScannerError(
        'while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.getMark(),
      );
    }
    if (LINEBREAKS.has(ch)) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (!breaks.length) chunks.push(' ');
      chunks.push(...breaks);
    } else {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalarBreaks(double, startMark) {
    const chunks = [];
    for (;;) {
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && BLANK_BREAK_OR_NULL.has(this.peek(3))) {
        throw new ScannerError(
          'while scanning a quoted scalar', startMark,
          'found unexpected document separator', this.getMark(),
        );
      }
      while (SPACE_TAB.has(this.peek())) this.forward();
      if (LINEBREAKS.has(this.peek())) {
        chunks.push(this.scanLineBreak());
      } else {
        return chunks;
      }
    }
  }

  scanPlain() {
    const chunks = [];
    const startMark = this.getMark();
    let endMark = startMark;
    const indent = this.indent + 1;
    let spaces = [];
    for (;;) {
      if (this.peek() === '#') break;
      let length = 0;
      for (;;) {
        const ch = this.peek(length);
        if (
          BLANK_BREAK_OR_NULL.has(ch) ||
          (ch === ':' &&
            (this.flowLevel
              ? PLAIN_COLON_FLOW_END.has(this.peek(length + 1))
              : BLANK_BREAK_OR_NULL.has(this.peek(length + 1)))) ||
          (this.flowLevel && FLOW_INDICATORS.has(ch))
        ) {
          break;
        }
        length += 1;
      }
      if (length === 0) break;
      this.allowSimpleKey = false;
      chunks.push(...spaces);
      chunks.push(this.prefix(length));
      this.forward(length);
      endMark = this.getMark();
      spaces = this.scanPlainSpaces(indent, startMark);
      if (
        spaces === null || spaces.length === 0 || this.peek() === '#' ||
        (!this.flowLevel && this.column < indent)
      ) {
        break;
      }
    }
    return new ScalarToken(chunks.join(''), true, startMark, endMark, null);
  }

  scanPlainSpaces(indent, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === ' ') length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (LINEBREAKS.has(ch)) {
      const lineBreak = this.scanLineBreak();
      this.allowSimpleKey = true;
      let prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && BLANK_BREAK_OR_NULL.has(this.peek(3))) {
        return null;
      }
      const breaks = [];
      while (this.peek() === ' ' || LINEBREAKS.has(this.peek())) {
        if (this.peek() === ' ') {
          this.forward();
        } else {
          breaks.push(this.scanLineBreak());
          prefix = this.prefix(3);
          if ((prefix === '---' || prefix === '...') && BLANK_BREAK_OR_NULL.has(this.peek(3))) {
            return null;
          }
        }
      }
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (!breaks.length) chunks.push(' ');
      chunks.push(...breaks);
    } else if (whitespaces) {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanTagHandle(name, startMark) {
    let ch = this.peek();
    if (ch !== '!') {
      throw new ScannerError(
        `while scanning a ${name}`, startMark,
        `expected '!', but found ${pyRepr(ch)}`, this.getMark(),
      );
    }
    let length = 1;
    ch = this.peek(length);
    if (ch !== ' ') {
      while (isNameChar(ch)) {
        length += 1;
        ch = this.peek(length);
      }
      if (ch !== '!') {
        this.forward(length);
        throw new ScannerError(
          `while scanning a ${name}`, startMark,
          `expected '!', but found ${pyRepr(ch)}`, this.getMark(),
        );
      }
      length += 1;
    }
    const value = this.prefix(length);
    this.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    const chunks = [];
    let length = 0;
    let ch = this.peek(length);
    while (isTagUriChar(ch)) {
      if (ch === '%') {
        chunks.push(this.prefix(length));
        this.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length += 1;
      }
      ch = this.peek(length);
    }
    if (length) {
      chunks.push(this.prefix(length));
      this.forward(length);
      length = 0;
    }
    if (!chunks.length) {
      throw new ScannerError(
        `while parsing a ${name}`, startMark,
        `expected URI, but found ${pyRepr(ch)}`, this.getMark(),
      );
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    const codes = [];
    const mark = this.getMark();
    while (this.peek() === '%') {
      this.forward();
      for (let k = 0; k < 2; k += 1) {
        if (!isHexDigit(this.peek(k))) {
          throw new ScannerError(
            `while scanning a ${name}`, startMark,
            `expected URI escape sequence of 2 hexdecimal numbers, but found ${pyRepr(this.peek(k))}`,
            this.getMark(),
          );
        }
      }
      codes.push(hexValue(this.peek(0)) * 16 + hexValue(this.peek(1)));
      this.forward(2);
    }
    try {
      return utf8Decode(codes);
    } catch (exc) {
      throw new ScannerError(`while scanning a ${name}`, startMark, exc.message, mark);
    }
  }

  scanLineBreak() {
    const ch = this.peek();
    if (ch === '\r' || ch === '\n' || ch === NEL) {
      if (this.prefix(2) === '\r\n') this.forward(2);
      else this.forward();
      return '\n';
    }
    if (ch === LS || ch === PS) {
      this.forward();
      return ch;
    }
    return '';
  }
}

/**
 * Python's `chr()` accepts lone surrogates; `String.fromCodePoint` does too, so
 * this only needs to guard the out-of-range case that `\U` escapes can produce.
 */
function codePointToString(code, startMark, scanner) {
  if (code > 0x10ffff) {
    throw new ScannerError(
      'while scanning a double-quoted scalar', startMark,
      `found unknown escape character ${pyRepr(String(code))}`, scanner.getMark(),
    );
  }
  return String.fromCodePoint(code);
}

/** Strict UTF-8 decode of a byte array, mirroring Python's bytes.decode('utf-8'). */
function utf8Decode(bytes) {
  let out = '';
  let i = 0;
  const fail = (start, end, reason) => {
    const err = new Error(
      `'utf-8' codec can't decode byte${end - start > 1 ? 's' : ''} in position ` +
      `${start}${end - start > 1 ? '-' + (end - 1) : ''}: ${reason}`,
    );
    throw err;
  };
  while (i < bytes.length) {
    const b0 = bytes[i];
    if (b0 < 0x80) {
      out += String.fromCharCode(b0);
      i += 1;
      continue;
    }
    let extra;
    let cp;
    if (b0 >= 0xc2 && b0 <= 0xdf) { extra = 1; cp = b0 & 0x1f; }
    else if (b0 >= 0xe0 && b0 <= 0xef) { extra = 2; cp = b0 & 0x0f; }
    else if (b0 >= 0xf0 && b0 <= 0xf4) { extra = 3; cp = b0 & 0x07; }
    else fail(i, i + 1, 'invalid start byte');
    if (i + extra >= bytes.length + 0 && i + extra > bytes.length - 1) {
      fail(i, bytes.length, 'unexpected end of data');
    }
    for (let k = 1; k <= extra; k += 1) {
      const b = bytes[i + k];
      if (b === undefined || (b & 0xc0) !== 0x80) fail(i, i + k + 1, 'invalid continuation byte');
      cp = (cp << 6) | (b & 0x3f);
    }
    if (cp >= 0xd800 && cp <= 0xdfff) fail(i, i + extra + 1, 'invalid continuation byte');
    if (cp > 0x10ffff) fail(i, i + extra + 1, 'invalid continuation byte');
    out += String.fromCodePoint(cp);
    i += extra + 1;
  }
  return out;
}

