  constructor(startMark = null, endMark = null, explicit = null, version = null, tags = null) {
    super(startMark, endMark);
    this.kind = 'DocumentStart';
    this.explicit = explicit;
    this.version = version;
    this.tags = tags;
  }
}

export class DocumentEndEvent extends Event {
  constructor(startMark = null, endMark = null, explicit = null) {
    super(startMark, endMark);
    this.kind = 'DocumentEnd';
    this.explicit = explicit;
  }
}

export class AliasEvent extends Event {
  constructor(anchor, startMark = null, endMark = null) {
    super(startMark, endMark);
    this.kind = 'Alias';
    this.anchor = anchor;
  }
}

export class ScalarEvent extends Event {
  constructor(anchor, tag, implicit, value, startMark = null, endMark = null, style = null) {
    super(startMark, endMark);
    this.kind = 'Scalar';
    this.anchor = anchor;
    this.tag = tag;
    this.implicit = implicit;
    this.value = value;
    this.style = style;
  }
}

export class SequenceStartEvent extends Event {
  constructor(anchor, tag, implicit, startMark = null, endMark = null, flowStyle = null) {
    super(startMark, endMark);
    this.kind = 'SequenceStart';
    this.anchor = anchor;
    this.tag = tag;
    this.implicit = implicit;
    this.flowStyle = flowStyle;
  }
}

export class SequenceEndEvent extends Event {
  constructor(startMark = null, endMark = null) {
