/**
 * YAML parser: turns tokens into events (port of PyYAML's `yaml.parser.Parser`).
 *
 * The original is a table of bound-method states; this keeps the same shape
 * using method-name strings so the control flow stays comparable.
 */

import { ParserError } from './errors.mjs';
import { pyRepr } from './pyrepr.mjs';
import { Scanner } from './scanner.mjs';
import {
  AliasEvent,
  DocumentEndEvent,
  DocumentStartEvent,
  MappingEndEvent,
  MappingStartEvent,
  ScalarEvent,
  SequenceEndEvent,
  SequenceStartEvent,
  StreamEndEvent,
  StreamStartEvent,
} from './events.mjs';

const DEFAULT_TAGS = new Map([
  ['!', '!'],
  ['!!', 'tag:yaml.org,2002:'],
]);

export class Parser {
  constructor(text) {
    this.scanner = new Scanner(text);
    this.currentEvent = null;
    this.yamlVersion = null;
    this.tagHandles = new Map();
    this.states = [];
    this.marks = [];
    this.state = 'parseStreamStart';
  }

  // ---- scanner shortcuts ------------------------------------------------

  checkToken(...ids) {
    return this.scanner.checkToken(...ids);
  }

  peekToken() {
    return this.scanner.peekToken();
  }

  getToken() {
    return this.scanner.getToken();
  }

  // ---- public event API -------------------------------------------------

  checkEvent(...kinds) {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this[this.state]();
    }
    if (this.currentEvent !== null) {
      if (!kinds.length) return true;
      return kinds.includes(this.currentEvent.kind);
    }
    return false;
  }

  peekEvent() {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this[this.state]();
    }
    return this.currentEvent;
  }

  getEvent() {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this[this.state]();
    }
    const event = this.currentEvent;
    this.currentEvent = null;
    return event;
  }

  // ---- document structure ----------------------------------------------

  parseStreamStart() {
    const token = this.getToken();
    const event = new StreamStartEvent(token.startMark, token.endMark, token.encoding);
    this.state = 'parseImplicitDocumentStart';
    return event;
  }

  parseImplicitDocumentStart() {
    if (!this.checkToken('<directive>', '<document start>', '<stream end>')) {
      this.tagHandles = new Map(DEFAULT_TAGS);
      const token = this.peekToken();
      const mark = token.startMark;
      const event = new DocumentStartEvent(mark, mark, false);
      this.states.push('parseDocumentEnd');
      this.state = 'parseBlockNode';
      return event;
    }
    return this.parseDocumentStart();
  }

  parseDocumentStart() {
    while (this.checkToken('<document end>')) this.getToken();
    if (!this.checkToken('<stream end>')) {
      let token = this.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.checkToken('<document start>')) {
        throw new ParserError(
          null, null,
          `expected '<document start>', but found ${pyRepr(this.peekToken().id)}`,
          this.peekToken().startMark,
        );
      }
      token = this.getToken();
      const event = new DocumentStartEvent(startMark, token.endMark, true, version, tags);
      this.states.push('parseDocumentEnd');
      this.state = 'parseDocumentContent';
      return event;
    }
    const token = this.getToken();
    const event = new StreamEndEvent(token.startMark, token.endMark);
    this.state = null;
    return event;
  }

  parseDocumentEnd() {
    let token = this.peekToken();
    const startMark = token.startMark;
    let endMark = token.startMark;
    let explicit = false;
    if (this.checkToken('<document end>')) {
      token = this.getToken();
      endMark = token.endMark;
      explicit = true;
    }
    const event = new DocumentEndEvent(startMark, endMark, explicit);
    this.state = 'parseDocumentStart';
    return event;
  }

  parseDocumentContent() {
    if (this.checkToken('<directive>', '<document start>', '<document end>', '<stream end>')) {
      const event = this.processEmptyScalar(this.peekToken().startMark);
      this.state = this.states.pop();
      return event;
    }
    return this.parseBlockNode();
  }

  processDirectives() {
    this.yamlVersion = null;
    this.tagHandles = new Map();
    while (this.checkToken('<directive>')) {
      const token = this.getToken();
      if (token.tokenName === 'YAML') {
        if (this.yamlVersion !== null) {
          throw new ParserError(null, null, 'found duplicate YAML directive', token.startMark);
        }
        const [major] = token.value;
        if (major !== 1) {
          throw new ParserError(
            null, null,
            'found incompatible YAML document (version 1.* is required)',
            token.startMark,
          );
        }
        this.yamlVersion = token.value;
      } else if (token.tokenName === 'TAG') {
        const [handle, prefix] = token.value;
        if (this.tagHandles.has(handle)) {
          throw new ParserError(
            null, null, `duplicate tag handle ${pyRepr(handle)}`, token.startMark,
          );
        }
        this.tagHandles.set(handle, prefix);
      }
    }
    const value = this.tagHandles.size
      ? [this.yamlVersion, new Map(this.tagHandles)]
      : [this.yamlVersion, null];
    for (const [key, prefix] of DEFAULT_TAGS) {
      if (!this.tagHandles.has(key)) this.tagHandles.set(key, prefix);
    }
    return value;
  }

  // ---- nodes ------------------------------------------------------------

  parseBlockNode() {
    return this.parseNode(true, false);
  }

  parseFlowNode() {
    return this.parseNode(false, false);
  }

  parseBlockNodeOrIndentlessSequence() {
    return this.parseNode(true, true);
  }

  parseNode(block = false, indentlessSequence = false) {
    if (this.checkToken('<alias>')) {
      const token = this.getToken();
      const event = new AliasEvent(token.value, token.startMark, token.endMark);
      this.state = this.states.pop();
      return event;
    }

    let anchor = null;
    let tag = null;
    let startMark = null;
    let endMark = null;
    let tagMark = null;
    let token;

    if (this.checkToken('<anchor>')) {
      token = this.getToken();
      startMark = token.startMark;
      endMark = token.endMark;
      anchor = token.value;
      if (this.checkToken('<tag>')) {
        token = this.getToken();
        tagMark = token.startMark;
        endMark = token.endMark;
        tag = token.value;
      }
    } else if (this.checkToken('<tag>')) {
      token = this.getToken();
      startMark = token.startMark;
      tagMark = token.startMark;
      endMark = token.endMark;
      tag = token.value;
      if (this.checkToken('<anchor>')) {
        token = this.getToken();
        endMark = token.endMark;
        anchor = token.value;
      }
    }

    if (tag !== null) {
      const [handle, suffix] = tag;
      if (handle !== null) {
        if (!this.tagHandles.has(handle)) {
          throw new ParserError(
            'while parsing a node', startMark,
            `found undefined tag handle ${pyRepr(handle)}`, tagMark,
          );
        }
        tag = this.tagHandles.get(handle) + suffix;
      } else {
        tag = suffix;
      }
    }

    if (startMark === null) {
      startMark = this.peekToken().startMark;
      endMark = startMark;
    }

    let implicit = tag === null || tag === '!';

    if (indentlessSequence && this.checkToken('-')) {
      endMark = this.peekToken().endMark;
      const event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, null);
      this.state = 'parseIndentlessSequenceEntry';
      return event;
    }

    if (this.checkToken('<scalar>')) {
      token = this.getToken();
      endMark = token.endMark;
      let scalarImplicit;
      if ((token.plain && tag === null) || tag === '!') scalarImplicit = [true, false];
      else if (tag === null) scalarImplicit = [false, true];
      else scalarImplicit = [false, false];
      const event = new ScalarEvent(
        anchor, tag, scalarImplicit, token.value, startMark, endMark, token.style,
      );
      this.state = this.states.pop();
      return event;
    }
    if (this.checkToken('[')) {
      endMark = this.peekToken().endMark;
      const event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, true);
      this.state = 'parseFlowSequenceFirstEntry';
      return event;
    }
    if (this.checkToken('{')) {
      endMark = this.peekToken().endMark;
      const event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark, true);
      this.state = 'parseFlowMappingFirstKey';
      return event;
    }
    if (block && this.checkToken('<block sequence start>')) {
      endMark = this.peekToken().startMark;
      const event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, false);
      this.state = 'parseBlockSequenceFirstEntry';
      return event;
    }
    if (block && this.checkToken('<block mapping start>')) {
      endMark = this.peekToken().startMark;
      const event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark, false);
      this.state = 'parseBlockMappingFirstKey';
      return event;
    }
    if (anchor !== null || tag !== null) {
      const event = new ScalarEvent(
        anchor, tag, [implicit, false], '', startMark, endMark, null,
      );
      this.state = this.states.pop();
      return event;
    }

    const node = block ? 'block' : 'flow';
    token = this.peekToken();
    throw new ParserError(
      `while parsing a ${node} node`, startMark,
      `expected the node content, but found ${pyRepr(token.id)}`, token.startMark,
    );
  }

  // ---- block collections ------------------------------------------------

  parseBlockSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockSequenceEntry();
  }

  parseBlockSequenceEntry() {
    if (this.checkToken('-')) {
      const token = this.getToken();
      if (!this.checkToken('-', '<block end>')) {
        this.states.push('parseBlockSequenceEntry');
        return this.parseBlockNode();
      }
      this.state = 'parseBlockSequenceEntry';
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken('<block end>')) {
      const token = this.peekToken();
      throw new ParserError(
        'while parsing a block collection', this.marks[this.marks.length - 1],
        `expected <block end>, but found ${pyRepr(token.id)}`, token.startMark,
      );
    }
    const token = this.getToken();
    const event = new SequenceEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseIndentlessSequenceEntry() {
    if (this.checkToken('-')) {
      const token = this.getToken();
      if (!this.checkToken('-', '?', ':', '<block end>')) {
        this.states.push('parseIndentlessSequenceEntry');
        return this.parseBlockNode();
      }
      this.state = 'parseIndentlessSequenceEntry';
      return this.processEmptyScalar(token.endMark);
    }
    const token = this.peekToken();
    const event = new SequenceEndEvent(token.startMark, token.startMark);
    this.state = this.states.pop();
    return event;
  }

  parseBlockMappingFirstKey() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockMappingKey();
  }

  parseBlockMappingKey() {
    if (this.checkToken('?')) {
      const token = this.getToken();
      if (!this.checkToken('?', ':', '<block end>')) {
        this.states.push('parseBlockMappingValue');
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = 'parseBlockMappingValue';
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken('<block end>')) {
      const token = this.peekToken();
      throw new ParserError(
        'while parsing a block mapping', this.marks[this.marks.length - 1],
        `expected <block end>, but found ${pyRepr(token.id)}`, token.startMark,
      );
    }
    const token = this.getToken();
    const event = new MappingEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseBlockMappingValue() {
    if (this.checkToken(':')) {
      const token = this.getToken();
      if (!this.checkToken('?', ':', '<block end>')) {
        this.states.push('parseBlockMappingKey');
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = 'parseBlockMappingKey';
      return this.processEmptyScalar(token.endMark);
    }
    this.state = 'parseBlockMappingKey';
    return this.processEmptyScalar(this.peekToken().startMark);
  }

  // ---- flow collections -------------------------------------------------

  parseFlowSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowSequenceEntry(true);
  }

  parseFlowSequenceEntry(first = false) {
    if (!this.checkToken(']')) {
      if (!first) {
        if (this.checkToken(',')) {
          this.getToken();
        } else {
          const token = this.peekToken();
          throw new ParserError(
            'while parsing a flow sequence', this.marks[this.marks.length - 1],
            `expected ',' or ']', but got ${pyRepr(token.id)}`, token.startMark,
          );
        }
      }
      if (this.checkToken('?')) {
        const token = this.peekToken();
        const event = new MappingStartEvent(
          null, null, true, token.startMark, token.endMark, true,
        );
        this.state = 'parseFlowSequenceEntryMappingKey';
        return event;
      }
      if (!this.checkToken(']')) {
        this.states.push('parseFlowSequenceEntry');
        return this.parseFlowNode();
      }
    }
    const token = this.getToken();
    const event = new SequenceEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseFlowSequenceEntryMappingKey() {
    const token = this.getToken();
    if (!this.checkToken(':', ',', ']')) {
      this.states.push('parseFlowSequenceEntryMappingValue');
      return this.parseFlowNode();
    }
    this.state = 'parseFlowSequenceEntryMappingValue';
    return this.processEmptyScalar(token.endMark);
  }

  parseFlowSequenceEntryMappingValue() {
    if (this.checkToken(':')) {
      const token = this.getToken();
      if (!this.checkToken(',', ']')) {
        this.states.push('parseFlowSequenceEntryMappingEnd');
        return this.parseFlowNode();
      }
      this.state = 'parseFlowSequenceEntryMappingEnd';
      return this.processEmptyScalar(token.endMark);
    }
    this.state = 'parseFlowSequenceEntryMappingEnd';
    return this.processEmptyScalar(this.peekToken().startMark);
  }

  parseFlowSequenceEntryMappingEnd() {
    this.state = 'parseFlowSequenceEntry';
    const token = this.peekToken();
    return new MappingEndEvent(token.startMark, token.startMark);
  }

  parseFlowMappingFirstKey() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowMappingKey(true);
  }

  parseFlowMappingKey(first = false) {
    if (!this.checkToken('}')) {
      if (!first) {
        if (this.checkToken(',')) {
          this.getToken();
        } else {
          const token = this.peekToken();
          throw new ParserError(
            'while parsing a flow mapping', this.marks[this.marks.length - 1],
            `expected ',' or '}', but got ${pyRepr(token.id)}`, token.startMark,
          );
        }
      }
      if (this.checkToken('?')) {
        const token = this.getToken();
        if (!this.checkToken(':', ',', '}')) {
          this.states.push('parseFlowMappingValue');
          return this.parseFlowNode();
        }
        this.state = 'parseFlowMappingValue';
        return this.processEmptyScalar(token.endMark);
      }
      if (!this.checkToken('}')) {
        this.states.push('parseFlowMappingEmptyValue');
        return this.parseFlowNode();
      }
    }
    const token = this.getToken();
    const event = new MappingEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseFlowMappingValue() {
    if (this.checkToken(':')) {
      const token = this.getToken();
      if (!this.checkToken(',', '}')) {
        this.states.push('parseFlowMappingKey');
        return this.parseFlowNode();
      }
      this.state = 'parseFlowMappingKey';
      return this.processEmptyScalar(token.endMark);
    }
    this.state = 'parseFlowMappingKey';
    return this.processEmptyScalar(this.peekToken().startMark);
  }

  parseFlowMappingEmptyValue() {
    this.state = 'parseFlowMappingKey';
    return this.processEmptyScalar(this.peekToken().startMark);
  }

  processEmptyScalar(mark) {
    return new ScalarEvent(null, null, [true, false], '', mark, mark, null);
  }
}

