/**
 * Implicit tag resolution (port of PyYAML's `yaml.resolver.Resolver`).
 *
 * PyYAML expresses each rule as a regular expression; since regular
 * expressions are off limits here, every pattern is hand-rolled as a scanner
 * over the code points of the scalar. The rules are registered in the same
 * order PyYAML registers them, because order decides ties (e.g. float is
 * tried before int for values starting with a digit).
 */

import { codePoints, isDigit, isHexDigit, asciiLower } from './chars.mjs';

export const DEFAULT_SCALAR_TAG = 'tag:yaml.org,2002:str';
export const DEFAULT_SEQUENCE_TAG = 'tag:yaml.org,2002:seq';
export const DEFAULT_MAPPING_TAG = 'tag:yaml.org,2002:map';

/** Cursor over an array of code points, with the primitives the rules need. */
class Cur {
  constructor(cps) {
    this.cps = cps;
    this.i = 0;
  }

  get atEnd() {
    return this.i >= this.cps.length;
  }

  peek(offset = 0) {
    const ch = this.cps[this.i + offset];
    return ch === undefined ? null : ch;
  }

  /** Consume `ch` if present. */
  eat(ch) {
    if (this.peek() === ch) {
      this.i += 1;
      return true;
    }
    return false;
  }

  /** Consume one character if `pred` accepts it. */
  eatIf(pred) {
    const ch = this.peek();
    if (ch !== null && pred(ch)) {
      this.i += 1;
      return true;
    }
    return false;
  }

  /** Consume as many `pred` characters as possible; returns the count. */
  eatWhile(pred) {
    let n = 0;
    while (this.eatIf(pred)) n += 1;
    return n;
  }

  eatLiteral(text) {
    const chars = codePoints(text);
    for (let k = 0; k < chars.length; k += 1) {
      if (this.cps[this.i + k] !== chars[k]) return false;
    }
    this.i += chars.length;
    return true;
  }
}

const isUnderscoreDigit = (ch) => isDigit(ch) || ch === '_';
const isOctalOrUnderscore = (ch) => (ch >= '0' && ch <= '7') || ch === '_';
const isBinaryOrUnderscore = (ch) => ch === '0' || ch === '1' || ch === '_';
const isHexOrUnderscore = (ch) => isHexDigit(ch) || ch === '_';
const isSpaceOrTab = (ch) => ch === ' ' || ch === '\t';

/** `[-+]?` */
function eatSign(c) {
  if (c.peek() === '-' || c.peek() === '+') c.i += 1;
}

// ---------------------------------------------------------------------------
// bool
// ---------------------------------------------------------------------------

const BOOL_WORDS = new Set([
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
]);

function matchBool(value) {
  return BOOL_WORDS.has(value);
}

// ---------------------------------------------------------------------------
// float
// ---------------------------------------------------------------------------

/** `(?:[eE][-+][0-9]+)?` — note the sign is mandatory in PyYAML's pattern. */
function eatExponent(c) {
  const save = c.i;
  if (!c.eatIf((ch) => ch === 'e' || ch === 'E')) return true;
  if (!c.eatIf((ch) => ch === '-' || ch === '+')) {
    c.i = save;
    return false;
  }
  if (c.eatWhile(isDigit) === 0) {
    c.i = save;
    return false;
  }
  return true;
}

function matchFloat(value) {
  const cps = codePoints(value);

  // [-+]?(?:[0-9][0-9_]*)\.[0-9_]*(?:[eE][-+][0-9]+)?
  let c = new Cur(cps);
  eatSign(c);
  if (c.eatIf(isDigit)) {
    c.eatWhile(isUnderscoreDigit);
    if (c.eat('.')) {
      c.eatWhile(isUnderscoreDigit);
      if (eatExponent(c) && c.atEnd) return true;
    }
  }

  // \.[0-9_]+(?:[eE][-+][0-9]+)?
  c = new Cur(cps);
  if (c.eat('.') && c.eatWhile(isUnderscoreDigit) > 0) {
    if (eatExponent(c) && c.atEnd) return true;
  }

  // [-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*
  c = new Cur(cps);
  eatSign(c);
  if (c.eatIf(isDigit)) {
    c.eatWhile(isUnderscoreDigit);
    if (eatSexagesimalGroups(c)) {
      if (c.eat('.')) {
        c.eatWhile(isUnderscoreDigit);
        if (c.atEnd) return true;
      }
    }
  }

  // [-+]?\.(?:inf|Inf|INF)
  c = new Cur(cps);
  eatSign(c);
  if (c.eat('.')) {
    for (const word of ['inf', 'Inf', 'INF']) {
      const save = c.i;
      if (c.eatLiteral(word) && c.atEnd) return true;
      c.i = save;
    }
  }

  // \.(?:nan|NaN|NAN)
  c = new Cur(cps);
  if (c.eat('.')) {
    for (const word of ['nan', 'NaN', 'NAN']) {
      const save = c.i;
      if (c.eatLiteral(word) && c.atEnd) return true;
      c.i = save;
    }
  }

  return false;
}

/** `(?::[0-5]?[0-9])+` — at least one group. */
function eatSexagesimalGroups(c) {
  let groups = 0;
  for (;;) {
    const save = c.i;
    if (!c.eat(':')) break;
    // [0-5]?[0-9] is greedy on the optional part but backtracks.
    let ok = false;
    if (c.peek() !== null && c.peek() >= '0' && c.peek() <= '5') {
      const twoSave = c.i;
      c.i += 1;
      if (c.eatIf(isDigit)) ok = true;
      else c.i = twoSave;
    }
    if (!ok) ok = c.eatIf(isDigit);
    if (!ok) {
      c.i = save;
      break;
    }
    groups += 1;
  }
  return groups > 0;
}

// ---------------------------------------------------------------------------
// int
// ---------------------------------------------------------------------------

function matchInt(value) {
  const cps = codePoints(value);

  // [-+]?0b[0-1_]+
  let c = new Cur(cps);
  eatSign(c);
  if (c.eatLiteral('0b') && c.eatWhile(isBinaryOrUnderscore) > 0 && c.atEnd) return true;

  // [-+]?0[0-7_]+
  c = new Cur(cps);
  eatSign(c);
  if (c.eat('0') && c.eatWhile(isOctalOrUnderscore) > 0 && c.atEnd) return true;

  // [-+]?(?:0|[1-9][0-9_]*)
  c = new Cur(cps);
  eatSign(c);
  if (c.eat('0') && c.atEnd) return true;
  c = new Cur(cps);
  eatSign(c);
  if (c.eatIf((ch) => ch >= '1' && ch <= '9')) {
    c.eatWhile(isUnderscoreDigit);
    if (c.atEnd) return true;
  }

  // [-+]?0x[0-9a-fA-F_]+
  c = new Cur(cps);
  eatSign(c);
  if (c.eatLiteral('0x') && c.eatWhile(isHexOrUnderscore) > 0 && c.atEnd) return true;

  // [-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+
  c = new Cur(cps);
  eatSign(c);
  if (c.eatIf((ch) => ch >= '1' && ch <= '9')) {
    c.eatWhile(isUnderscoreDigit);
    if (eatSexagesimalGroups(c) && c.atEnd) return true;
  }

  return false;
}

// ---------------------------------------------------------------------------
// null / merge / value
// ---------------------------------------------------------------------------

const NULL_WORDS = new Set(['~', 'null', 'Null', 'NULL', '']);

function matchNull(value) {
  return NULL_WORDS.has(value);
}

// ---------------------------------------------------------------------------
// timestamp
// ---------------------------------------------------------------------------

/**
 * ^(?:[0-9]{4}-[0-9]{2}-[0-9]{2}
 *   |[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}
 *    (?:[Tt]|[ \t]+)[0-9]{1,2}:[0-9]{2}:[0-9]{2}(?:\.[0-9]*)?
 *    (?:[ \t]*(?:Z|[-+][0-9]{1,2}(?::[0-9]{2})?))?)$
 */
function matchTimestamp(value) {
  const cps = codePoints(value);

  // Date-only form: exactly YYYY-MM-DD.
  let c = new Cur(cps);
  if (eatN(c, 4, isDigit) && c.eat('-') && eatN(c, 2, isDigit) && c.eat('-') &&
      eatN(c, 2, isDigit) && c.atEnd) {
    return true;
  }

  c = new Cur(cps);
  if (!eatN(c, 4, isDigit)) return false;
  if (!c.eat('-')) return false;
  if (!eatOneOrTwo(c)) return false;
  if (!c.eat('-')) return false;
  if (!eatOneOrTwo(c)) return false;
  if (c.peek() === 'T' || c.peek() === 't') c.i += 1;
  else if (c.eatWhile(isSpaceOrTab) === 0) return false;
  if (!eatOneOrTwo(c)) return false;
  if (!c.eat(':')) return false;
  if (!eatN(c, 2, isDigit)) return false;
  if (!c.eat(':')) return false;
  if (!eatN(c, 2, isDigit)) return false;
  if (c.eat('.')) c.eatWhile(isDigit);
  const save = c.i;
  c.eatWhile(isSpaceOrTab);
  if (c.eat('Z')) {
    // done
  } else if (c.peek() === '-' || c.peek() === '+') {
    c.i += 1;
    if (!eatOneOrTwo(c)) return false;
    const tzSave = c.i;
    if (c.eat(':')) {
      if (!eatN(c, 2, isDigit)) {
        c.i = tzSave;
      }
    }
  } else {
    c.i = save;
  }
  return c.atEnd;
}

function eatN(c, n, pred) {
  const save = c.i;
  for (let k = 0; k < n; k += 1) {
    if (!c.eatIf(pred)) {
      c.i = save;
      return false;
    }
  }
  return true;
}

/** `[0-9][0-9]?` */
function eatOneOrTwo(c) {
  if (!c.eatIf(isDigit)) return false;
  c.eatIf(isDigit);
  return true;
}

// ---------------------------------------------------------------------------
// registry
// ---------------------------------------------------------------------------

/**
 * Rules in registration order, each with the set of allowed first characters
 * PyYAML uses to index them. `''` means "matches the empty scalar".
 */
const IMPLICIT_RULES = [
  { tag: 'tag:yaml.org,2002:bool', first: 'yYnNtTfFoO', test: matchBool },
  { tag: 'tag:yaml.org,2002:float', first: '-+0123456789.', test: matchFloat },
  { tag: 'tag:yaml.org,2002:int', first: '-+0123456789', test: matchInt },
  { tag: 'tag:yaml.org,2002:merge', first: '<', test: (v) => v === '<<' },
  { tag: 'tag:yaml.org,2002:null', first: '~nN�EMPTY', test: matchNull },
  { tag: 'tag:yaml.org,2002:timestamp', first: '0123456789', test: matchTimestamp },
  { tag: 'tag:yaml.org,2002:value', first: '=', test: (v) => v === '=' },
  { tag: 'tag:yaml.org,2002:yaml', first: '!&*', test: (v) => v === '!' || v === '&' || v === '*' },
];

/** first-character -> ordered rule list; the empty key covers empty scalars. */
const RESOLVERS = new Map();
for (const rule of IMPLICIT_RULES) {
  const firsts = rule.tag === 'tag:yaml.org,2002:null'
    ? ['~', 'n', 'N', '']
    : codePoints(rule.first);
  for (const ch of firsts) {
    if (!RESOLVERS.has(ch)) RESOLVERS.set(ch, []);
    RESOLVERS.get(ch).push(rule);
  }
}

/**
 * @param {'scalar'|'sequence'|'mapping'} kind
 * @param {string} value
 * @param {[boolean, boolean]} implicit
 */
export function resolve(kind, value, implicit) {
  if (kind === 'scalar' && implicit[0]) {
    const first = value === '' ? '' : codePoints(value)[0];
    const rules = RESOLVERS.get(first);
    if (rules) {
      for (const rule of rules) {
        if (rule.test(value)) return rule.tag;
      }
    }
  }
  if (kind === 'scalar') return DEFAULT_SCALAR_TAG;
  if (kind === 'sequence') return DEFAULT_SEQUENCE_TAG;
  return DEFAULT_MAPPING_TAG;
}

export { asciiLower };

