// registry
// ---------------------------------------------------------------------------

/**
 * Rules in registration order, each with the set of allowed first characters
 * PyYAML uses to index them. `''` means "matches the empty scalar".
 */
const IMPLICIT_RULES = [
  { tag: 'tag:yaml.org,2002:bool', first: 'yYnNtTfFoO', test: matchBool },
  { tag: 'tag:yaml.org,2002:float', first: '-+0123456789.', test: matchFloat },
  { tag: 'tag:yaml.org,2002:int', first: '-+0123456789', test: matchInt },
  { tag: 'tag:yaml.org,2002:merge', first: '<', test: (v) => v === '<<' },
  { tag: 'tag:yaml.org,2002:null', first: '~nN�EMPTY', test: matchNull },
  { tag: 'tag:yaml.org,2002:timestamp', first: '0123456789', test: matchTimestamp },
  { tag: 'tag:yaml.org,2002:value', first: '=', test: (v) => v === '=' },
  { tag: 'tag:yaml.org,2002:yaml', first: '!&*', test: (v) => v === '!' || v === '&' || v === '*' },
