/** first-character -> ordered rule list; the empty key covers empty scalars. */
const RESOLVERS = new Map();
for (const rule of IMPLICIT_RULES) {
  const firsts = rule.tag === 'tag:yaml.org,2002:null'
    ? ['~', 'n', 'N', '']
    : codePoints(rule.first);
  for (const ch of firsts) {
    if (!RESOLVERS.has(ch)) RESOLVERS.set(ch, []);
    RESOLVERS.get(ch).push(rule);
  }
}

/**
 * @param {'scalar'|'sequence'|'mapping'} kind
 * @param {string} value
 * @param {[boolean, boolean]} implicit
 */
export function resolve(kind, value, implicit) {
  if (kind === 'scalar' && implicit[0]) {
    const first = value === '' ? '' : codePoints(value)[0];
    const rules = RESOLVERS.get(first);
    if (rules) {
      for (const rule of rules) {
        if (rule.test(value)) return rule.tag;
      }
    }
